\begin{tikzpicture}[x=20mm,y=20mm,draw=black,text=black,font=\fontsize{10}{12}\selectfont]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\pgfmathsetmacro{\s}{sin(11.25)}
\pgfmathsetmacro{\h}{cos(11.25)}
\coordinate (O) at (-3,0.5);
\draw[line width=0.8pt] (O) circle[radius=1];
\foreach \a in {0,22.5,...,337.5}{\draw[line width=0.4pt,dashed] (O)--++(\a:1);}
\fill (O) circle[radius=0.6mm];
\path (O)--++(0:1) node[pos=0.7,above] {$r$};
\draw[line width=0.8pt,-latex] (-1.45,0.55)--(-0.65,0.55);
\foreach \k in {0,...,7}{
\pgfmathsetmacro{\xl}{2*\k*\s}
\pgfmathsetmacro{\xt}{(2*\k+1)*\s}
\pgfmathsetmacro{\xb}{(2*\k+2)*\s}
\pgfmathsetmacro{\xr}{(2*\k+3)*\s}
\draw[line width=0.8pt] (\xl,0) arc[start angle=258.75,end angle=281.25,radius=1];
\draw[line width=0.8pt] (\xt,\h) arc[start angle=101.25,end angle=78.75,radius=1];
\draw[line width=0.4pt,dashed] (\xl,0)--(\xt,\h)--(\xb,0)--(\xr,\h);
}
\draw[line width=0.5pt,latex-latex] (0,-0.24)--({16*\s},-0.24) node[midway,below] {$\pi r$};
\draw[line width=0.5pt,latex-latex] ({17*\s+0.25},0)--({17*\s+0.25},\h) node[midway,right] {$r$};
\path (-4.1,-0.85) rectangle ({17*\s+0.85},1.65);
\end{tikzpicture}

